def semver_sort(versions):
    def parse(v):
        main = v
        build = None
        if '+' in main:
            main, build = main.split('+', 1)
        pre = None
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core = main
        major, minor, patch = (int(x) for x in core.split('.'))
        return major, minor, patch, pre

    def pre_key(pre):
        if pre is None:
            return None
        idents = pre.split('.')
        key = []
        for ident in idents:
            if ident.isdigit():
                key.append((0, int(ident)))
            else:
                key.append((1, ident))
        return key

    def sort_key(v):
        major, minor, patch, pre = parse(v)
        has_pre = 0 if pre is not None else 1
        pk = pre_key(pre) if pre is not None else []
        return (major, minor, patch, has_pre, pk)

    return sorted(versions, key=sort_key)

